pub struct ExtractResult {
    pub query: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    pub value: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct StepResult {
    pub ok: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<StepError>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub new_state_hash: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub extract: Option<ExtractResult>,
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn action_round_trip_click() {
        let action = Action::Click {
            id: "el_42".to_string(),
        };
        let value = serde_json::to_value(&action).expect("serialize action");
        assert_eq!(value, json!({"type": "click", "id": "el_42"}));
        let parsed: Action = serde_json::from_value(value).expect("deserialize action");
        assert_eq!(parsed, action);
    }

    #[test]
    fn action_rejects_unknown_type() {
        let value = json!({"type": "teleport", "id": "el_1"});
        let parsed: Result<Action, _> = serde_json::from_value(value);
        assert!(parsed.is_err(), "expected unknown action type to fail");
    }

    #[test]
    fn action_requires_type_tag() {
        let value = json!({"id": "el_1"});
        let parsed: Result<Action, _> = serde_json::from_value(value);
        assert!(parsed.is_err(), "expected missing type tag to fail");
    }

    #[test]
    fn observation_round_trip() {
        let observation = Observation {
            url: "https://example.com".to_string(),
            title: "Example".to_string(),
            viewport: [1280, 800],
            focused: Some("el_7".to_string()),
            visible_text: "Hello".to_string(),
            state_hash: "ab12cd".to_string(),
            elements: vec![ElementRef {
                id: "el_7".to_string(),
                role: "textbox".to_string(),
                name: Some("Email".to_string()),
                value: None,
                bbox: [10.0, 120.0, 400.0, 36.0],
                flags: ElementFlags {
                    focused: Some(true),
                    ..ElementFlags::default()
                },
            }],
        };
        let value = serde_json::to_value(&observation).expect("serialize observation");
        assert_eq!(value.get("state_hash"), Some(&json!("ab12cd")));
        assert_eq!(value.get("focused"), Some(&json!("el_7")));
        let parsed: Observation =
            serde_json::from_value(value).expect("deserialize observation");
        assert_eq!(parsed, observation);
    }

    #[test]
    fn step_result_round_trip() {
        let result = StepResult {
            ok: false,
            error: Some(StepError {
                code: "invalid_action".to_string(),
                message: "missing id".to_string(),
            }),
            new_state_hash: None,
            extract: None,
        };
        let value = serde_json::to_value(&result).expect("serialize step result");
        let parsed: StepResult = serde_json::from_value(value).expect("deserialize step result");
        assert_eq!(parsed, result);
    }

    #[test]
    fn step_result_with_extract_round_trip() {
        let result = StepResult {
            ok: true,
            error: None,
            new_state_hash: None,
            extract: Some(ExtractResult {
                query: "price".to_string(),
                id: Some("el_4".to_string()),
                value: "$10".to_string(),
            }),
        };
        let value = serde_json::to_value(&result).expect("serialize step result");
        let parsed: StepResult = serde_json::from_value(value).expect("deserialize step result");
        assert_eq!(parsed, result);
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn e2e_snapshot_actionable_nodes() {
    let server = TestServer::start().await;
    let url = server.url("/harness");
    let config = CdpConfig {
        initial_url: url,
        ..CdpConfig::default()
    };
    let browser = CdpBrowser::launch(config).await.expect("launch browser");

    let snapshot = browser.snapshot().await.expect("snapshot");
    assert!(
        snapshot.elements.len() >= 10,
        "expected at least 10 actionable elements, got {}",
        snapshot.elements.len()
    );

    browser.shutdown().await.expect("shutdown browser");
    server.shutdown().await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn e2e_click_type_select() {
    let server = TestServer::start().await;
    let url = server.url("/harness");
    let config = CdpConfig {
        initial_url: url,
        ..CdpConfig::default()
    };
    let browser = CdpBrowser::launch(config).await.expect("launch browser");
    let validator = Validator::default();

    let snapshot = browser.snapshot().await.expect("initial snapshot");
    let click_id = find_element(&snapshot, "button", "Click Button").id.clone();
    let click = Action::Click { id: click_id };
    validator.validate(&click, &snapshot).expect("valid click");
    let step = browser.apply(&click).await.expect("apply click");
    assert!(step.ok);

    let snapshot = browser.snapshot().await.expect("snapshot after click");
    assert!(
        snapshot.visible_text.contains("clicked"),
        "visible text should reflect click"
    );

    let type_id = find_element_by_roles(&snapshot, &["textbox", "searchbox"], "Name")
        .id
        .clone();
    let focus = Action::Click { id: type_id.clone() };
    validator.validate(&focus, &snapshot).expect("valid focus");
    let step = browser.apply(&focus).await.expect("apply focus");
    assert!(step.ok);

    let typed = Action::Type {
        id: type_id,
        text: "Ada Lovelace".to_string(),
        submit: Some(false),
    };
    validator.validate(&typed, &snapshot).expect("valid type");
    let step = browser.apply(&typed).await.expect("apply type");
    assert!(step.ok);

    let snapshot = wait_for_visible_text(&browser, "typed:Ada Lovelace").await;

    let submit_id = find_element_by_roles(&snapshot, &["textbox", "searchbox"], "Search")
        .id
        .clone();
    let submit = Action::Type {
        id: submit_id,
        text: "Lambda".to_string(),
        submit: Some(true),
    };
    validator.validate(&submit, &snapshot).expect("valid submit type");
    let step = browser.apply(&submit).await.expect("apply submit type");
    assert!(step.ok);

    let snapshot = wait_for_visible_text(&browser, "submitted:Lambda").await;

    let select_id = find_element_by_roles(&snapshot, &["combobox", "listbox"], "Choice")
        .id
        .clone();
    let select = Action::Select {
        id: select_id,
        value: "beta".to_string(),
    };
    validator.validate(&select, &snapshot).expect("valid select");
    let step = browser.apply(&select).await.expect("apply select");
    assert!(step.ok);

    let snapshot = wait_for_visible_text(&browser, "selected:beta").await;
    assert!(
        snapshot.visible_text.contains("selected:beta"),
        "visible text should reflect select change"
    );

    browser.shutdown().await.expect("shutdown browser");
    server.shutdown().await;
}

